INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Index immer schneller als eine Tabellensuche?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Datenmenge und Abfrage ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Indexierung?', 3, '[{"text": "Abfragegeschwindigkeit", "correct": true, "because": "Hauptziel der Indexierung"}, {"text": "Minimale Speichergröße", "correct": false, "because": "Leistung wichtiger"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Effizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Indizes gibt es?', 5, '[{"text": "B-Tree", "correct": true, "because": "Standard für schnelle Suchen"}, {"text": "Bitmap", "correct": true, "because": "Gut für niedrige Kardinalität"}, {"text": "Loop-Index", "correct": false, "because": "Kein echter Index-Typ"}, {"text": "Color-Index", "correct": false, "because": "Kein technischer Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Indizes beschleunigen SELECTs. b) Sie verlangsamen immer INSERTs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "INSERTs nicht immer langsamer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Indexierung?', 4, '[{"text": "Schlüsselspalten", "correct": false, "because": "Kern der Indexierung"}, {"text": "Abfragemuster", "correct": false, "because": "Bestimmt Effizienz"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Index auch bei kleinen Tabellen sinnvoll ist?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead oft nicht lohnend"}, {"text": "Ja", "correct": false, "because": "Meist bei großen Datenmengen effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Index wähle ich für eine Spalte mit wenigen eindeutigen Werten?', 3, '[{"text": "Bitmap", "correct": true, "because": "Effizient bei niedriger Kardinalität"}, {"text": "B-Tree", "correct": false, "because": "Besser für hohe Kardinalität"}, {"text": "Hash", "correct": false, "because": "Nur für exakte Übereinstimmungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen mir Indizes?', 5, '[{"text": "Schnellere Abfragen", "correct": true, "because": "Reduziert Suchzeit"}, {"text": "Effiziente Sortierung", "correct": true, "because": "Unterstützt ORDER BY"}, {"text": "Weniger Speicher", "correct": false, "because": "Erhöht Speicherbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Indizes verbessern WHERE-Bedingungen. b) Sie machen alle Abfragen schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle Abfragen profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Indexierung?', 4, '[{"text": "Spaltenauswahl", "correct": false, "because": "Bestimmt Index"}, {"text": "Abfrageanalyse", "correct": false, "because": "Optimiert Nutzen"}, {"text": "Spiele-Engine", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verlangsamen Indizes Schreiboperationen?', 2, '[{"text": "Ja", "correct": true, "because": "Index muss aktualisiert werden"}, {"text": "Nein", "correct": false, "because": "Häufiger Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Indexierung effektiv?', 4, '[{"text": "Geeignete Spalten", "correct": true, "because": "Häufig abgefragt"}, {"text": "Regelmäßige Wartung", "correct": true, "because": "Sichert Effizienz"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Indizes nur für Primärschlüssel sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Spalten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Index?', 3, '[{"text": "Selektivität", "correct": true, "because": "Verbessert Effizienz"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Leistung wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Nutzen zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) B-Tree ist Standard für Indizes. b) Indizes sind immer einzigartig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Indizes können doppelt sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen profitieren von Indizes?', 5, '[{"text": "SELECT", "correct": true, "because": "Schnellere Suche"}, {"text": "JOIN", "correct": true, "because": "Effiziente Verknüpfung"}, {"text": "INSERT", "correct": false, "because": "Wird verlangsamt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Index wähle ich für exakte Übereinstimmungen?', 4, '[{"text": "Hash", "correct": true, "because": "Optimal für Gleichheitssuchen"}, {"text": "B-Tree", "correct": false, "because": "Besser für Bereiche"}, {"text": "Bitmap", "correct": false, "because": "Für niedrige Kardinalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Index mehrere Spalten umfassen?', 3, '[{"text": "Ja", "correct": true, "because": "Composite Index möglich"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Indizes automatisch aktualisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Bei Datenänderung angepasst"}, {"text": "Nein", "correct": false, "because": "Automatischer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel passt zur Indexierung?', 4, '[{"text": "Suche nach Kundennamen", "correct": true, "because": "Häufig abgefragt"}, {"text": "Tabellenstruktur ändern", "correct": false, "because": "DDL-Aufgabe"}, {"text": "Berechtigungen vergeben", "correct": false, "because": "DCL-Aufgabe"}]');
